INSERT INTO public.products(category_id,code,refs,application,stock,price_cash,price_30,price_30_45_60,price_30_45_60_75,manufacturer,active,price_note)
SELECT c.id,i.code,i.refs,i.application,i.stock,i.price_cash,i.price_30,i.price_30_45_60,i.price_30_45_60_75,'FCO',true,'Tabela atacado 10/2026'
FROM incoming i JOIN public.categories c ON c.name=i.category
ON CONFLICT(code) DO UPDATE SET
 category_id=EXCLUDED.category_id,refs=EXCLUDED.refs,application=EXCLUDED.application,stock=EXCLUDED.stock,
 price_cash=EXCLUDED.price_cash,price_30=EXCLUDED.price_30,price_30_45_60=EXCLUDED.price_30_45_60,
 price_30_45_60_75=EXCLUDED.price_30_45_60_75,manufacturer='FCO',active=true,price_note='Tabela atacado 10/2026';
COMMIT;
